// Shared loaders and invariants for the heavy corpus tests (`npm run test:data`).
// The corpora are regenerated by tools/datasets/build-corpora.mjs, so these checks
// compare each corpus against its own manifest and structural invariants;
// exact row counts belong in the manifest checksums, not in tests.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {missingFiles, readJsonl, readJsonlText, repoUrl} from '../helpers.mjs';

export const SPLITS = ['train', 'dev', 'test'];

/** Project-relative split files: train/dev under datasets/, sealed test under eval/suites/. */
export function splitFiles(name) {
  return {train: `datasets/${name}/train.jsonl`, dev: `datasets/${name}/dev.jsonl`, test: `eval/suites/${name}/test.jsonl`};
}

/** Skip reason when a corpus (or any extra file it needs) is absent, else false. */
export function corpusSkip(name, ...extra) {
  return missingFiles(`corpus ${name}`, ...Object.values(splitFiles(name)), ...extra);
}

/** Load a corpus once per process: parsed rows and raw text of each split file. */
const loaded = new Map();
export function loadCorpus(name) {
  if (!loaded.has(name)) {
    const files = splitFiles(name);
    const text = Object.fromEntries(SPLITS.map(split => [split, readJsonlText(repoUrl(files[split]))]));
    const bySplit = Object.fromEntries(SPLITS.map(split => [split, text[split].trimEnd().split('\n').map(JSON.parse)]));
    loaded.set(name, {files, text, bySplit, rows: SPLITS.flatMap(split => bySplit[split])});
  }
  return loaded.get(name);
}

export const loadRows = relative => readJsonl(repoUrl(relative));

/**
 * Structural split invariants shared by every corpus:
 * - every split file is nonempty and holds only rows of its own split;
 * - row IDs are unique across the corpus (the sealed test is disjoint);
 * - every split group stays inside one split (no leakage through paraphrases,
 *   rewrites or contrast partners);
 * - the split proportions stay within broad bounds, so a regenerated corpus
 *   cannot silently collapse or inflate a split.
 */
export function assertSplitInvariants(bySplit, {group = row => row.split_group_id, bounds = {train: [0.6, 0.9], dev: [0.05, 0.25], test: [0.05, 0.25]}} = {}) {
  const total = SPLITS.reduce((sum, split) => sum + bySplit[split].length, 0);
  for (const split of SPLITS) {
    const rows = bySplit[split];
    assert.ok(rows.length > 0, `${split} split is empty`);
    const wrong = rows.find(row => row.split !== split);
    assert.equal(wrong, undefined, `${split} file contains a row of split ${wrong?.split}`);
    const share = rows.length / total;
    const [low, high] = bounds[split];
    assert.ok(share >= low && share <= high, `${split} holds ${(100 * share).toFixed(1)}% of rows, outside ${low}..${high}`);
  }
  const all = SPLITS.flatMap(split => bySplit[split]);
  assert.equal(new Set(all.map(row => row.id)).size, all.length, 'row IDs must be unique across splits');
  const owner = new Map();
  for (const row of all) {
    const key = group(row);
    const previous = owner.get(key);
    assert.ok(previous === undefined || previous === row.split, `${key}: split group crosses ${previous} and ${row.split}`);
    owner.set(key, row.split);
  }
}

/** Every value of every required family is represented at least once. */
export function assertFamiliesPresent(rows, families) {
  for (const [name, [key, required]] of Object.entries(families)) {
    const present = new Set(rows.map(key));
    for (const value of required) assert.ok(present.has(value), `no row for ${name}=${value}`);
  }
}
